/// <summary>
/// Reads MSBuild build properties from <c>AnalyzerConfigOptionsProvider.GlobalOptions</c>. A
/// property only reaches the generator when the project lists it in
/// <c>CompilerVisibleProperty</c>.
/// </summary>
internal static class AnalyzerConfigOptionsProviderExtensions
{
    /// <summary>Reads one build property, trimmed; a missing, empty or whitespace value is null.</summary>
    /// <param name="provider">The analyzer config options provider.</param>
    /// <param name="name">The property name, which the project must expose through <c>CompilerVisibleProperty</c>.</param>
    public static IncrementalValueProvider<string?> ForBuildProperty(
        this IncrementalValueProvider<AnalyzerConfigOptionsProvider> provider,
        string name)
