        return provider.Select((options, _) => Read(options, name));
    }

    /// <summary>Reads several build properties at once, each trimmed; blank values are null.</summary>
    /// <param name="provider">The analyzer config options provider.</param>
    /// <param name="names">The property names, which the project must expose through <c>CompilerVisibleProperty</c>.</param>
